import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/index.md","filePath":"recipes/index.md"}'),t={name:"recipes/index.md"};function s(n,e,l,p,c,d){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Short Lua examples for common desktop configuration tasks. Add a recipe to <code>~/.config/gnoblin/init.lua</code> after any <code>gnoblin.load(...)</code> lines so your choices override settings loaded from other files.</p><p>After editing the file, apply the changes with <code>gnoblinctl config reload</code>.</p><ul><li><a href="/recipes/complete-starter-config">Complete starter config</a>: start with a working shell, shortcut and window rule setup.</li><li><a href="/recipes/add-a-shortcut">Add a shortcut</a>: add or change one named shortcut without replacing other shortcuts.</li><li><a href="/recipes/dim-unfocused-windows">Dim unfocused windows</a>: lower the opacity of windows that are not focused.</li><li><a href="/recipes/round-application-windows">Round application windows</a>: set window corner radius and smoothing.</li><li><a href="/recipes/turn-off-layer-animations">Turn off layer animations</a>: disable compositor animations for layer surfaces.</li><li><a href="/recipes/request-a-titlebar">Request a Gnoblin titlebar</a>: provide a server titlebar when an application requests one.</li><li><a href="/recipes/combine-window-rules">Combine window rules</a>: apply defaults and override selected values for matching windows.</li><li><a href="/recipes/split-config-into-files">Split a config into files</a>: load separate files for appearance and shortcuts.</li><li><a href="/recipes/writing-workspace">Set up a writing workspace</a>: assign stable workspace IDs, place editor windows, and control workspaces from the CLI.</li><li><a href="/recipes/small-desktop">Build a small desktop</a>: start a bar, notifications, launcher and terminal.</li><li><a href="/recipes/laptop-input">Set up a laptop for two keyboard layouts</a>: configure XKB layouts, keyboard options and touchpad gestures.</li><li><a href="/recipes/pointer-feedback">Make pointer feedback easier to see</a>: enlarge the cursor and enable locate-pointer and visual-bell effects.</li><li><a href="/recipes/remote-support">Prepare remote support access</a>: scope screen-share and input permissions to one trusted program.</li><li><a href="/recipes/pen-display-workflow">Set up a pen display</a>: map a tablet and configure a stylus button.</li><li><a href="/recipes/organize-config-files">Organize a growing config</a>: split rules and shortcuts into loaded Lua files.</li><li><a href="/recipes/put-apps-on-named-workspaces">Route new app windows to named workspaces</a>: send new editor, browser and chat windows to stable workspace IDs.</li><li><a href="/recipes/animate-the-developer-console">Animate the developer console</a>: customize the built-in console&#39;s entrance and exit.</li><li><a href="/recipes/springy-app-entrance">Give an app a springy entrance</a>: register keyframes and apply them to one application.</li></ul><p>See the <a href="/config/configure">configuration reference</a> for available options and the <a href="/guides/window_rules">configuration guides</a> for behavior and tradeoffs.</p>',5)])])}const h=a(t,[["render",s]]);export{u as __pageData,h as default};
